/**
 * Judged-input capture for calibration records (mt#3607).
 *
 * A calibration record says what a detector DECIDED. Until this module, most
 * records did not say what it decided ABOUT — they stored a matched phrase (or
 * for the PR-body surfaces, nothing of the text at all), so a later reviewer
 * could not tell a true positive from a false one, and a re-check had to go
 * fetch a MUTABLE artifact whose current content may no longer be what was
 * judged. mt#3584 hit exactly that: a record written when a negative-control
 * label sat above the evidence block, re-checked after the body was edited so
 * the label sat inside it, reports clean. The historical false positive is
 * invisible.
 *
 * Two shipped precedents define the shape, and this module is deliberately a
 * consolidation of them rather than a third invention:
 *
 * - mt#3198 (`pre-narration`) — a bounded sentence of CONTEXT per match,
 *   extracted from the ELIDED text, stored under a NEW key. {@link
 *   extractMatchContext} is that implementation, moved here so the other
 *   turn-text detectors reuse it instead of copying it. `pre-narration-detector`
 *   re-exports it, exactly as `elision.ts` (mt#2672) did for the elision
 *   helpers, so its public API and tests are unchanged.
 * - mt#3576 (`wall-of-text`) — an `excerpt` PLUS a `textHash`. {@link
 *   captureArtifact} is that shape generalized. The hash is the load-bearing
 *   half: it makes a mutated artifact DETECTABLE rather than silently
 *   re-derivable to a different verdict.
 *
 * ## Why capture goes in a NEW key, never by widening an existing one
 *
 * `extractDistinctPhrases` in `src/domain/calibration/calibration-sweep.ts`
 * derives the review-due threshold's diversity axis from `matches[].phrase`.
 * Sentences are near-unique, so widening that field would make every record a
 * distinct "phrase" and silently destroy the count that decides when a log gets
 * reviewed. `calibration-sweep.ts` carries the same warning at its own source.
 *
 * ## Why capture runs on ELIDED text
 *
 * Widening what a detector writes to a log is the moment pasted tool output can
 * start reaching that log. Every turn-text caller already computes an elided
 * copy (code fences, inline spans, blockquotes, double-quoted prose blanked with
 * SAME-LENGTH whitespace, so offsets still address the same span) for its own
 * matching. Capture from that copy, never from the raw turn text — the elision
 * is what makes the wider window safe rather than a new exposure.
 *
 * ## Retention and redaction posture (mt#3872, decided 2026-08-12)
 *
 * The PR-body surfaces capture from an artifact that has NOT been elided — a PR
 * body or a spec is stored as written. The posture for those captures, decided
 * by the operator on ask#8157 rather than left implicit:
 *
 * - **Local-only.** Every calibration log is gitignored and none has ever been
 *   committed — all 31 `.minsky/*.jsonl` files verified against `.gitignore`,
 *   not assumed. The exposure is one working copy on one machine, and the PR
 *   bodies these captures hold are already public on GitHub.
 * - **Bounded and hashed.** {@link captureArtifact} stores at most
 *   {@link ARTIFACT_CAPTURE_MAX_CHARS} code units of the text, so an unbounded
 *   artifact cannot write an unbounded record. Alongside it,
 *   {@link hashJudgedText} stores a digest computed over the WHOLE text rather
 *   than over the stored excerpt — which is what makes a truncated capture
 *   still able to detect a mutated artifact. That digest is a 16-hex-character
 *   (64-bit) PREFIX of the sha256, not the full one: sized to notice an
 *   artifact that changed between the write and a re-check, and deliberately
 *   not sized against an adversary constructing a collision. No security
 *   property here rests on it.
 * - **Never redacted, deliberately.** Not an oversight and not a TODO. A
 *   redaction filter that matches nothing emits its input unchanged and is
 *   indistinguishable from one that fired, which is how a prod DB password
 *   leaked on 2026-08-01 (`terminal-command-best-practices.mdc §Secret
 *   handling`). Adding a regex redactor here would buy exactly that false
 *   assurance. The basis for saying so is a measurement, bounded to what was
 *   measured: on 2026-08-12 a ten-pattern secret-shape scan (tokens, keys,
 *   JWTs, bearer headers, credentialed URLs) over the 749 records then present
 *   across the three logs that carry captures matched nothing. That is a
 *   statement about that corpus on that date, not a guarantee about future
 *   records — reproduce it with `rg` over `.minsky/*-calibration.jsonl` before
 *   citing it as current.
 * - **Remedy if a secret is ever captured: delete the local log.** These are
 *   disposable calibration records with no retention requirement — there is no
 *   recovery procedure to run and nothing downstream depends on the history.
 *
 * Re-open this decision if the logs ever become committed, shipped off-machine,
 * or read by anything that outlives a local sweep; each of those removes a
 * premise the posture rests on.
 */

import { createHash } from "node:crypto";
import { safeTruncate } from "@minsky/shared/safe-truncate";

// ---------------------------------------------------------------------------
// Schema version
// ---------------------------------------------------------------------------

/**
 * Stamped on every record written by a writer that captures its judged input.
 *
 * This is mt#3607's fourth criterion: records written BEFORE the capture landed
 * must be mechanically distinguishable from records written after, so a future
 * `/calibration-review` does not treat an un-auditable record as comparable to
 * an auditable one. The check is `record.captureSchema === undefined` → written
 * before capture, judged text unrecoverable, NOT re-classifiable.
 *
 * A date cutover was rejected: log records are appended by whichever build is
 * installed, so a machine running an older hook writes old-shaped records after
 * the cutover date. The field travels with the record; a date does not.
 */
export const CAPTURE_SCHEMA_VERSION = 1;

/** The record key {@link CAPTURE_SCHEMA_VERSION} is written under. */
export const CAPTURE_SCHEMA_FIELD = "captureSchema";

/**
 * True when `record` was written by a writer that captured its judged input —
 * i.e. it is retrospectively re-classifiable. Readers should treat `false` as
 * "un-auditable", not as "no capture was needed".
 */
export function hasJudgedInputCapture(record: Record<string, unknown>): boolean {
  return typeof record[CAPTURE_SCHEMA_FIELD] === "number";
}

// ---------------------------------------------------------------------------
// Turn-text surfaces — a bounded sentence around the match
// ---------------------------------------------------------------------------

/**
 * Cap on the captured context, in UTF-16 code units.
 *
 * Sized to hold a normal prose sentence with room for a long one, and small
 * enough that the log stays a log rather than a transcript mirror. Moved here
 * verbatim from `pre-narration-detector.ts` (mt#3198), whose value this is.
 */
export const MATCH_CONTEXT_MAX_CHARS = 240;

/**
 * How far to scan outward from a match hunting for a sentence boundary before
 * giving up and cutting at the scan limit. Bounds the work done on a
 * pathological input (a wall of prose with no terminal punctuation) and keeps
 * the pre-truncation slice within a small multiple of the cap.
 */
const CONTEXT_SCAN_RADIUS = 300;

/** Tuning for {@link extractMatchContext}. */
export interface MatchContextOptions {
  /**
   * How many sentences BEFORE the containing one to include. Default 0 — the
   * containing sentence alone, which is `pre-narration`'s shipped behavior and
   * stays its behavior.
   *
   * `1` exists because a one-sentence window is not always enough, and which
   * case you are in is a property of the detector's CORPUS. Measured over
   * `.minsky/ask-routing-deferral-calibration.jsonl` (253 matches, 2026-08-05):
   * roughly 200 are short fragments — `Say the word` (103), `needs your call`
   * (35), `I'll stop here` (21), `you decide` (10) — for which the containing
   * sentence is exactly the missing information. But some of those fragments
   * ARE whole sentences on their own (`What's your call?`), and there the
   * containing sentence adds nothing at all: the real deferral and the courtesy
   * offer produce a byte-identical context, which is the very thing ask#7052
   * asked to be able to tell apart. One sentence of lead separates them.
   *
   * The cap in {@link MATCH_CONTEXT_MAX_CHARS} still applies, so this widens
   * what is SELECTED, never what is stored.
   */
  leadSentences?: 0 | 1;
}

/**
 * Extract the sentence or clause containing a match (mt#3198).
 *
 * **Call this with the ELIDED text, never the raw turn text** — see this
 * module's header for why, and note that every elision helper in
 * `.minsky/hooks/elision.ts` preserves character offsets, so an index computed
 * against the elided text addresses the same span here.
 *
 * Boundaries are `.`/`!`/`?` (a terminator followed by whitespace, going
 * backwards; the terminator itself going forwards) or a newline. This is a
 * deliberately simple splitter — an abbreviation or a decimal point can cut a
 * sentence short. That degrades the excerpt, it does not corrupt the record,
 * and a reviewer reading a slightly-short clause is still incomparably better
 * off than one reading the bare phrase `merged PR`.
 *
 * Whitespace runs (including the elision's blanks) collapse to single spaces so
 * one record stays one readable line.
 */
export function extractMatchContext(
  text: string,
  matchIndex: number,
  matchLength: number,
  options: MatchContextOptions = {}
): string {
  const leadSentences = options.leadSentences ?? 0;
  const lowerBound = Math.max(0, matchIndex - CONTEXT_SCAN_RADIUS);
  let start = lowerBound;
  let boundariesToCross = leadSentences + 1;
  for (let i = matchIndex - 1; i > lowerBound; i--) {
    const ch = text[i];
    const isBoundary =
      ch === "\n" || ((ch === "." || ch === "!" || ch === "?") && /\s/.test(text[i + 1] ?? " "));
    if (!isBoundary) continue;
    boundariesToCross -= 1;
    if (boundariesToCross === 0) {
      start = i + 1;
      break;
    }
  }

  const matchEnd = matchIndex + matchLength;
  const upperBound = Math.min(text.length, matchEnd + CONTEXT_SCAN_RADIUS);
  let end = upperBound;
  for (let i = matchEnd; i < upperBound; i++) {
    const ch = text[i];
    if (ch === "\n") {
      end = i;
      break;
    }
    if (ch === "." || ch === "!" || ch === "?") {
      end = i + 1;
      break;
    }
  }

  const raw = text.slice(start, end).replace(/\s+/g, " ").trim();
  return safeTruncate(raw, MATCH_CONTEXT_MAX_CHARS, "head");
}

// ---------------------------------------------------------------------------
// Artifact surfaces — a bounded excerpt plus a hash of the whole
// ---------------------------------------------------------------------------

/**
 * Cap on a captured artifact, in UTF-16 code units.
 *
 * GROUNDED IN OBSERVED SIZE, not a round number (`decision-defaults.mdc
 * §Thresholds`). Over the last 60 pull requests in this repo the body length
 * distribution was p50 7,235 / p90 10,619 / max 13,380 characters
 * (`gh api 'repos/edobry/minsky/pulls?state=all&per_page=60' --jq
 * '[.[] | .body | length] | sort'`, measured 2026-08-05). 16,000 clears the
 * observed maximum with ~20% headroom, so a truncated capture is the rare case
 * rather than the normal one — which matters because a truncated capture cannot
 * re-derive a verdict that turned on text past the cut.
 *
 * Sizing it this generously is affordable because these logs are NOT committed:
 * `.gitignore:56` excludes every `.minsky/<name>-calibration.jsonl` by pattern,
 * and `git ls-files '.minsky/<glob>-calibration.jsonl'` returns 0. The real cost
 * of an oversized capture is reviewability (a log that becomes a transcript
 * mirror stops being readable), not repo weight.
 */
export const ARTIFACT_CAPTURE_MAX_CHARS = 16_000;

/** A bounded snapshot of a judged artifact, plus enough to detect mutation. */
export interface ArtifactCapture {
  /** The artifact text, truncated at {@link ARTIFACT_CAPTURE_MAX_CHARS}. */
  excerpt: string;
  /** sha256 of the FULL text (first 16 hex chars) — mirrors mt#3576's `textHash`. */
  hash: string;
  /** Length of the FULL text, before truncation. */
  length: number;
  /** True when `excerpt` is shorter than the artifact — re-derivation is then PARTIAL. */
  truncated: boolean;
}

/**
 * Hash a judged artifact. sha256, first 16 hex chars — the exact convention
 * `wall-of-text-detector.ts` already writes under `textHash`, so a reader that
 * understands one understands the other.
 */
export function hashJudgedText(text: string): string {
  return createHash("sha256").update(text).digest("hex").slice(0, 16);
}

/**
 * Snapshot an artifact (a PR body, a spec) the way {@link ArtifactCapture}
 * describes.
 *
 * `truncated` is recorded rather than inferred so a reader never has to guess
 * whether an excerpt ending mid-sentence was the whole input. A re-check over a
 * truncated record must report "partial", never a verdict — the same discipline
 * mem#704 states for any probe that would return the same answer with its input
 * missing.
 */
export function captureArtifact(
  text: string,
  maxChars: number = ARTIFACT_CAPTURE_MAX_CHARS
): ArtifactCapture {
  return {
    excerpt: safeTruncate(text, maxChars, "head"),
    hash: hashJudgedText(text),
    length: text.length,
    truncated: text.length > maxChars,
  };
}
